-- AI review queue rows are generated by trusted database-side processing and
-- resolved through SECURITY DEFINER RPCs. The browser only reads the queue
-- and calls ai_resolve_review_task(); it does not need direct DML privileges.
DROP POLICY IF EXISTS "company members insert" ON public.ai_review_queue;
DROP POLICY IF EXISTS "company members update" ON public.ai_review_queue;

REVOKE INSERT, UPDATE ON TABLE public.ai_review_queue
FROM PUBLIC, anon, authenticated;
